	@Test
	void quantityGetterFailureAndCloseKeepExactObjectsInQuoteAndBoundary() {
		for (boolean boundary : new boolean[] { false, true }) {
			for (boolean lineageGetter : new boolean[] { false, true }) {
				for (RuntimeException failure : new RuntimeException[] {
						new IllegalArgumentException("provider getter"),
						new QueryInterruptedException("provider cancellation"),
						new PackedProviderWork.Exhausted() }) {
					var cleanup = new IllegalStateException("provider close");
					AtomicInteger closes = new AtomicInteger();
					RuntimeException observed = assertThrows(RuntimeException.class, () -> runProvider(true,
							(factory, work, memory, context) -> {
								try (var region = ready(factory.open())) {
									var root = region.root();
									var left = ready(region.child(root, 0));
									var proof = ready(region.cover(root,
											new PackedPhysicalRegion.Occurrence[] { root, left }));
									try (var request = ready(factory.openStrategyRequest(region, root, context));
											var active = ready(request.activate())) {
										var candidate = ready(request.recognize(ready(request.bindCoverage(proof))));
										var quantity = new PackedStrategyRequest.Quantity() {
											@Override
											public PackedStrategyRequest.Dimension dimension() {
												if (!lineageGetter) {
													throw failure;
												}
												return PackedStrategyRequest.Dimension.SOURCE_ROW_EVENTS;
											}

											@Override
											public double lower() {
												return 0;
											}

											@Override
											public double point() {
												return 0;
											}

											@Override
											public double upper() {
												return 0;
											}

											@Override
											public PackedStrategyRequest.Lineage lineage() {
												if (lineageGetter) {
													throw failure;
												}
												return PackedStrategyRequest.Lineage.EXACT;
											}
										};
										if (boundary) {
											request.boundary(candidate, 0,
													PackedStrategyRequest.BoundaryScope.INCLUSIVE,
													new PackedStrategyRequest.Quantity[] { quantity });
										} else {
											request.quote(candidate, new PackedStrategyRequest.Quantity[] { quantity });
										}
									}
								}
							}, () -> {
								closes.incrementAndGet();
								throw cleanup;
							}));
					assertSame(failure, observed);
					assertEquals(1, closes.get());
					assertEquals(1, failure.getSuppressed().length);
					assertSame(cleanup, failure.getSuppressed()[0]);
				}
			}
		}
	}

	@Test
	void signedZeroUnknownIsUnavailableWithFreshBuilder() {
		checkSignedZero(false);
	}

	@Test
	void signedZeroUnknownIsUnavailableWithMaterializedBuilder() {
		checkSignedZero(true);
	}

	private static void checkSignedZero(boolean materializeIntervals) {
		runProvider(true, (factory, work, memory, context) -> {
			try (var region = ready(factory.open())) {
				var root = region.root();
				var left = ready(region.child(root, 0));
				var proof = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root, left }));
				// The first actual factory in this planner session owns memo generation 1.
				assertTrue(work instanceof PackedCascadesPlanner.ProviderWorkBinding);
				var arena = ((PackedCascadesPlanner.ProviderWorkBinding) work).vectors(1L);
				assertEquals(1L, arena.builderResetWork(), "the actual owner starts without interval-builder storage");
				try (var request = ready(factory.openStrategyRequest(region, root, context));
						var active = ready(request.activate())) {
					var candidate = ready(request.recognize(ready(request.bindCoverage(proof))));
					var dimension = PackedStrategyRequest.Dimension.SOURCE_ROW_EVENTS;
					if (materializeIntervals) {
						ready(request.quote(candidate, new PackedStrategyRequest.Quantity[] {
								new Value(dimension, 1, 2, 3, PackedStrategyRequest.Lineage.UNKNOWN) }));
						assertTrue(arena.builderResetWork() > 1L, "the actual owner materialized interval storage");
					}
					List<Executable> assertions = new ArrayList<>();
					for (double lower : new double[] { -0.0d, 0.0d }) {
						for (double point : new double[] { -0.0d, 0.0d }) {
							for (double upper : new double[] { -0.0d, 0.0d }) {
								String detail = Double.toHexString(lower) + ", " + Double.toHexString(point) + ", "
										+ Double.toHexString(upper);
								var exact = new Value(dimension, lower, point, upper,
										PackedStrategyRequest.Lineage.EXACT);
								var quote = ready(
										request.quote(candidate, new PackedStrategyRequest.Quantity[] { exact }));
								var boundary = ready(request.boundary(candidate, 0,
										PackedStrategyRequest.BoundaryScope.INCLUSIVE,
										new PackedStrategyRequest.Quantity[] { exact }));
								var vector = ready(request.compose(candidate, quote,
										new PackedStrategyRequest.Boundary[] { boundary }));
								assertTrue(vector.isKnown(dimension), "exact zero is known: " + detail);
								assertTrue(vector.lower(dimension) == 0.0d, "exact lower: " + detail);
								assertTrue(vector.point(dimension) == 0.0d, "exact point: " + detail);
								assertTrue(vector.upper(dimension) == 0.0d, "exact upper: " + detail);
								assertEquals(PackedStrategyRequest.Lineage.EXACT, vector.lineage(dimension), detail);
								var unknown = new Value(dimension, lower, point, upper,
										PackedStrategyRequest.Lineage.UNKNOWN);
								assertions.add(() -> assertEquals(PackedPhysicalRegion.Status.EVIDENCE_UNAVAILABLE,
										request.quote(candidate, new PackedStrategyRequest.Quantity[] { unknown })
												.status(),
										"quote " + detail));
								assertions.add(() -> assertEquals(PackedPhysicalRegion.Status.EVIDENCE_UNAVAILABLE,
										request.boundary(candidate, 0, PackedStrategyRequest.BoundaryScope.INCLUSIVE,
												new PackedStrategyRequest.Quantity[] { unknown }).status(),
										"boundary " + detail));
							}
						}
					}
					for (var invalid : new Value[] {
							new Value(dimension, Double.NaN, 1, 2, PackedStrategyRequest.Lineage.EXACT),
							new Value(dimension, 0, Double.POSITIVE_INFINITY, 2, PackedStrategyRequest.Lineage.EXACT),
							new Value(dimension, 0, 1, Double.POSITIVE_INFINITY, PackedStrategyRequest.Lineage.EXACT),
							new Value(dimension, -1, 0, 1, PackedStrategyRequest.Lineage.EXACT),
							new Value(dimension, 2, 1, 3, PackedStrategyRequest.Lineage.EXACT),
							new Value(dimension, 0, 4, 3, PackedStrategyRequest.Lineage.UNKNOWN) }) {
						assertThrows(IllegalArgumentException.class,
								() -> request.quote(candidate, new PackedStrategyRequest.Quantity[] { invalid }));
						assertThrows(IllegalArgumentException.class,
								() -> request.boundary(candidate, 0, PackedStrategyRequest.BoundaryScope.INCLUSIVE,
										new PackedStrategyRequest.Quantity[] { invalid }));
					}
					assertEquals(materializeIntervals, arena.builderResetWork() > 1L,
							"exact-zero controls preserve the intended actual builder state");
					assertAll(assertions);
				}
			}
		}, () -> {
		});
	}

	@Test
	void cancellationPrecedesNormalEarlyOutcomes() {
		runProvider(true, (factory, work, memory, context) -> {
			try (var region = ready(factory.open())) {
				var root = region.root();
				var inner = ready(region.child(root, 1));
				var proof = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root }));
				var innerProof = ready(region.cover(inner, new PackedPhysicalRegion.Occurrence[] { inner }));
				try (var request = ready(factory.openStrategyRequest(region, root, context));
						var active = ready(request.activate())) {
					var candidate = ready(request.recognize(ready(request.bindCoverage(proof))));
					assertAll(
							() -> interrupted(() -> request.recognizeNested(candidate, 1, innerProof)),
							() -> interrupted(() -> request.quote(candidate, new PackedStrategyRequest.Quantity[0])),
							() -> interrupted(() -> request.boundary(candidate, 1,
									PackedStrategyRequest.BoundaryScope.LOCAL, quantities(1))),
							() -> interrupted(() -> request.detach(candidate, "rdf4j.test", "fused", -1)));
				}
			}
		}, () -> {
		});
	}

