	private static void closedAttemptCannotHideRefusal(boolean memoryRefusal) {
		runProvider(true, (factory, work, memory, context) -> {
			try (var region = ready(factory.open())) {
				var root = region.root();
				var left = ready(region.child(root, 0));
				var proof = ready(region.cover(root, new PackedPhysicalRegion.Occurrence[] { root, left }));
				try (var request = ready(factory.openStrategyRequest(region, root, context))) {
					var active = ready(request.activate());
					var candidate = ready(request.recognize(ready(request.bindCoverage(proof))));
					var quote = ready(request.quote(candidate, quantities(9)));
					var boundary = ready(request.boundary(candidate, 0,
							PackedStrategyRequest.BoundaryScope.INCLUSIVE, quantities(20)));
					active.close();
					assertFalse(memoryRefusal ? memory.tryReserve(Long.MAX_VALUE)
							: work.tryReserve(work.remainingWorkUnits() + 1));
					assertAll(
							() -> assertThrows(IllegalStateException.class,
									() -> request.quote(candidate, quantities(9))),
							() -> assertThrows(IllegalStateException.class, () -> request.compose(candidate, quote,
									new PackedStrategyRequest.Boundary[] { boundary })),
							() -> assertThrows(IllegalStateException.class,
									() -> request.detach(candidate, "rdf4j.test", "fused", 1)),
							() -> assertThrows(IllegalStateException.class, request::activate),
							() -> assertThrows(IllegalStateException.class, candidate::coverage),
							() -> assertThrows(IllegalStateException.class, quote::coverage),
							() -> assertThrows(IllegalStateException.class, boundary::occurrence));
				}
			}
		}, () -> {
		});
	}

